def decode_cyclic(s: str):
    """Decode a string encoded with encode_cyclic."""
    groups = [s[i:i + 3] for i in range(0, len(s), 3)]
    return "".join(group[-1:] + group[:-1] if len(group) == 3 else group for group in groups)

def by_length(arr):
    names = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five", 6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"}
    return [names[n] for n in sorted((n for n in arr if n in names), reverse=True)]
